choose.when:
SELECT 

WHERE m.conversation_id = #{conversationId}
  AND m.status IN (0, 1)
  AND (

          m.id > #{afterMessageId} OR 
          m.create_time > #{afterTime} OR 

  )

ORDER BY m.id ASC
LIMIT #{limit}

SELECT 
FROM (
    SELECT 

    WHERE m.conversation_id = #{conversationId}
      AND m.status IN (0, 1)
      AND m.id < #{beforeMessageId}

    ORDER BY m.id DESC
    LIMIT #{limit}
) recent
ORDER BY recent.messageId ASC

choose.otherwise:
SELECT 
FROM (
    SELECT 

    WHERE m.conversation_id = #{conversationId}
      AND m.status IN (0, 1)

    ORDER BY m.id DESC
    LIMIT #{limit}
) recent
ORDER BY recent.messageId ASC
